function useRemote(url,version=0){const [state,setState]=useState({data:null,error:''});useEffect(()=>{let active=true;setState({data:null,error:''});api(url).then(data=>{if(active)setState({data,error:''});}).catch(e=>{if(active)setState({data:null,error:e.message});});return()=>{active=false;};},[url,version]);return state;}
function Badge({status}){return <span className={'badge '+status}>{statuses[status]||({publish:'Publicat',draft:'Ciornă',instock:'Disponibil',outofstock:'Indisponibil',new:'Nou',read:'Citit',resolved:'Rezolvat',paid:'Achitat',unpaid:'Neachitat',refunded:'Restituit'}[status])||status}</span>;}
function Field({label,value,onChange,type='text',required=false,options,wide=false}){return <label className={wide?'full':''}>{label}{type==='textarea'?<textarea value={value??''} onChange={e=>onChange(e.target.value)} required={required}/>:type==='select'?<select value={value??''} onChange={e=>onChange(e.target.value)}>{options.map(o=><option key={o[0]} value={o[0]}>{o[1]}</option>)}</select>:type==='checkbox'?<span className="field-check"><input type="checkbox" checked={!!value} onChange={e=>onChange(e.target.checked?1:0)}/>{value?'Activ':'Inactiv'}</span>:<input type={type==='money'?'number':type} step={type==='money'?'0.01':type==='number'?'1':undefined} min={type==='money'||type==='number'?0:undefined} value={type==='money'?(value===null||value===undefined?'':value/100):(value??'')} onChange={e=>onChange(type==='money'?(e.target.value===''?null:Math.round(Number(e.target.value)*100)):type==='number'?(e.target.value===''?null:Number(e.target.value)):e.target.value)} required={required}/>}</label>;}
function SEO({value,onChange}){const v=value||{};return <details className="seo-editor"><summary>SEO și distribuire</summary><div className="admin-form-grid">{[['title','Meta title'],['description','Meta description'],['canonical','Canonical'],['og_image','Imagine Open Graph']].map(([k,l])=><Field key={k} label={l} value={v[k]} onChange={x=>onChange({...v,[k]:x})} wide/>)}<Field label="Exclude din indexare" type="checkbox" value={v.noindex} onChange={x=>onChange({...v,noindex:!!x})}/></div></details>;}
function ImagePicker({images,onChange,single=false}){const r=useRemote('/admin/media'),[open,setOpen]=useState(false),[search,setSearch]=useState('');return <div className="image-picker"><div className="chosen-images">{images.map((i,n)=><div key={i.url}><Image src={i.url} alt={i.alt}/><button type="button" aria-label="Elimină imaginea" title="Elimină această imagine din galerie" onClick={()=>onChange(images.filter((_,x)=>x!==n))}>×</button><input aria-label="Text alternativ imagine" value={i.alt} onChange={e=>onChange(images.map((x,k)=>k===n?{...x,alt:e.target.value}:x))}/>{n>0&&<button type="button" className="image-first" title="Setează această imagine drept coperta produsului" onClick={()=>onChange([i,...images.filter((_,k)=>k!==n)])}>Imagine principală</button>}</div>)}</div><button className="admin-button" type="button" title="Deschide biblioteca media pentru a alege imagini" onClick={()=>setOpen(!open)}><ImageIcon size={17}/>Alege din bibliotecă</button>{open&&<div className="picker-library"><input placeholder="Caută o imagine…" aria-label="Caută imagine" value={search} onChange={e=>setSearch(e.target.value)}/><div>{r.data?.filter(m=>(m.name+' '+m.alt).toLowerCase().includes(search.toLowerCase())).map(m=><button type="button" key={m.id} title={"Alege imaginea "+m.name} onClick={()=>{const image={url:m.url,alt:m.alt};onChange(single?[image]:images.some(x=>x.url===m.url)?images:[...images,image]);setOpen(false);}}><Image src={m.url} alt={m.alt}/><small>{m.name}</small></button>)}</div></div>}</div>;}
function ProductCategoryPicker({categories=[],value=[],onChange}){
 const [open,setOpen]=useState(false),[search,setSearch]=useState(''),root=useRef(null),selected=value.map(Number);
 useEffect(()=>{const close=e=>{if(root.current&&!root.current.contains(e.target))setOpen(false);};const escape=e=>{if(e.key==='Escape')setOpen(false);};document.addEventListener('pointerdown',close);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',close);document.removeEventListener('keydown',escape);};},[]);
 const names=new Map(categories.map(category=>[Number(category.id),category.name]));
 const parentName=category=>category.parent_id?names.get(Number(category.parent_id)):'';
 const filtered=categories.filter(category=>smartSearchMatch([category.name,parentName(category)].filter(Boolean).join(' '),search));
 const toggle=category=>{const id=Number(category.id);let next=selected.includes(id)?selected.filter(item=>item!==id):[...selected,id];if(!selected.includes(id)&&category.parent_id)next=[...new Set([...next,Number(category.parent_id)])];onChange(next);};
 return <section className="premium-category-picker" ref={root}>
  <div className="premium-field-heading"><div><span>CATEGORII PRODUS</span><strong>Unde apare produsul</strong></div><small>{selected.length?`${selected.length} selectate`:'Nicio categorie selectată'}</small></div>
  <button className={'premium-category-trigger '+(open?'is-open':'')} type="button" aria-expanded={open} aria-controls="product-category-options" onClick={()=>setOpen(state=>!state)}>
   <span className="premium-category-trigger-icon"><Grid2X2 size={17}/></span>
   <span>{selected.length?selected.slice(0,3).map(id=>names.get(id)).filter(Boolean).join(', '):'Alege una sau mai multe categorii'}</span>
   {selected.length>3&&<em>+{selected.length-3}</em>}<ChevronDown size={17}/>
  </button>
  {selected.length>0&&<div className="premium-category-chips">{selected.map(id=>names.has(id)&&<span key={id}>{names.get(id)}<button type="button" aria-label={`Elimină categoria ${names.get(id)}`} onClick={()=>onChange(selected.filter(item=>item!==id))}>×</button></span>)}</div>}
  {open&&<div className="premium-category-menu" id="product-category-options">
   <div className="premium-category-search"><Search size={16}/><input autoFocus value={search} onChange={event=>setSearch(event.target.value)} placeholder="Caută o categorie…" aria-label="Caută o categorie"/>{search&&<button type="button" aria-label="Șterge căutarea" onClick={()=>setSearch('')}>×</button>}</div>
   <div className="premium-category-options" role="listbox" aria-multiselectable="true">
    {filtered.length?filtered.map(category=>{const active=selected.includes(Number(category.id));return <button type="button" role="option" aria-selected={active} className={(active?'is-selected ':'')+(category.parent_id?'is-child':'')} key={category.id} onClick={()=>toggle(category)}><span className="premium-category-check">{active&&<Check size={14}/>}</span><span><strong>{category.name}</strong>{category.parent_id&&<small>în {parentName(category)}</small>}</span></button>;}):<div className="premium-category-empty"><Search size={20}/><span>Nicio categorie nu corespunde căutării.</span></div>}
   </div>
   <footer><span>{selected.length} categorii selectate</span>{selected.length>0&&<button type="button" onClick={()=>onChange([])}>Golește selecția</button>}</footer>
  </div>}
 </section>;
}
function ProductMediaPicker({images=[],onChange,max=12}){
 const s=useStore(),[version,setVersion]=useState(0),library=useRemote('/admin/media',version),[open,setOpen]=useState(false),[search,setSearch]=useState(''),[uploading,setUploading]=useState(false),[dragged,setDragged]=useState(null),[over,setOver]=useState(null),inputRef=useRef(null);
 const setMain=index=>{if(index===0)return;const next=[...images],chosen=next.splice(index,1)[0];onChange([chosen,...next]);};
 const remove=index=>onChange(images.filter((_,itemIndex)=>itemIndex!==index));
 const reorder=(from,to)=>{if(from===null||from===to||from<0||to<0)return;const next=[...images],moved=next.splice(from,1)[0];next.splice(to,0,moved);onChange(next);};
 const move=(index,direction)=>reorder(index,index+direction);
 const uploadFiles=async files=>{const accepted=[...files].filter(file=>/^image\/(jpeg|png|webp)$/.test(file.type)).slice(0,Math.max(0,max-images.length));if(!accepted.length){s.notify(images.length>=max?`Galeria poate conține maximum ${max} imagini.`:'Alege imagini JPG, PNG sau WebP.','error');return;}setUploading(true);let next=[...images];try{for(const file of accepted){const body=new FormData();body.set('file',file);body.set('alt',file.name.replace(/\.[^.]+$/,''));const result=await api('/admin/media',{method:'POST',body});if(!next.some(item=>item.url===result.url))next.push({url:result.url,alt:file.name.replace(/\.[^.]+$/,'')});}onChange(next);setVersion(item=>item+1);s.notify(accepted.length===1?'Fotografia a fost adăugată.':`${accepted.length} fotografii au fost adăugate.`);}catch(error){s.notify(error.message,'error');}finally{setUploading(false);if(inputRef.current)inputRef.current.value='';}};
 const available=(library.data||[]).filter(item=>smartSearchMatch([item.name,item.alt].join(' '),search));
 return <section className="premium-product-media" onDragOver={event=>{if(event.dataTransfer?.types?.includes('Files'))event.preventDefault();}} onDrop={event=>{if(event.dataTransfer?.files?.length){event.preventDefault();uploadFiles(event.dataTransfer.files);}}}>
  <header className="premium-media-heading"><div><span>MEDIA PRODUS</span><h3>Fotografiile produsului</h3><p>Prima fotografie este coperta din catalog. Trage cardurile pentru a schimba ordinea.</p></div><aside><strong>{images.length}/{max}</strong><small>JPG, PNG sau WebP · max. 8 MB</small></aside></header>
  <div className={'premium-media-gallery '+(over==='upload'?'is-file-over':'')}>
   {images.map((image,index)=><article className={'premium-media-card '+(index===0?'is-main ':'')+(over===index?'is-over ':'')+(dragged===index?'is-dragging':'')} key={`${image.url}-${index}`} draggable onDragStart={event=>{setDragged(index);event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(index));}} onDragOver={event=>{event.preventDefault();event.dataTransfer.dropEffect='move';setOver(index);}} onDrop={event=>{event.preventDefault();const from=dragged??Number(event.dataTransfer.getData('text/plain'));reorder(from,index);setDragged(null);setOver(null);}} onDragEnd={()=>{setDragged(null);setOver(null);}}>
    <div className="premium-media-preview"><Image src={image.url} alt={image.alt}/><span className="premium-media-grip" aria-hidden="true"><GripVertical size={17}/></span><button className="premium-media-remove" type="button" aria-label={`Elimină fotografia ${index+1}`} onClick={()=>remove(index)}>×</button>{index===0&&<span className="premium-media-main-label"><Star size={11} fill="currentColor"/>Principală</span>}</div>
    <div className="premium-media-card-footer"><label>Text alternativ<input value={image.alt||''} onChange={event=>onChange(images.map((item,itemIndex)=>itemIndex===index?{...item,alt:event.target.value}:item))} placeholder="Descrie fotografia"/></label><div className="premium-media-card-actions"><button type="button" disabled={index===0} aria-label={`Mută fotografia ${index+1} spre stânga`} onClick={()=>move(index,-1)}><ChevronLeft size={14}/></button><button type="button" className={index===0?'is-active':''} aria-label={index===0?'Aceasta este imaginea principală':`Setează fotografia ${index+1} ca imagine principală`} onClick={()=>setMain(index)}><Star size={15} fill={index===0?'currentColor':'none'}/><span>{index===0?'Copertă':'Alege coperta'}</span></button><button type="button" disabled={index===images.length-1} aria-label={`Mută fotografia ${index+1} spre dreapta`} onClick={()=>move(index,1)}><ChevronRight size={14}/></button></div></div>
   </article>)}
   {images.length<max&&<article className="premium-media-add" onDragEnter={()=>setOver('upload')} onDragLeave={()=>setOver(null)}>
    <input ref={inputRef} type="file" multiple accept="image/jpeg,image/png,image/webp" hidden onChange={event=>uploadFiles(event.target.files)}/><span><Camera size={21}/></span><strong>{uploading?'Se încarcă…':'Adaugă fotografii'}</strong><small>Selectează mai multe imagini<br/>sau trage-le aici</small><div><button type="button" disabled={uploading} onClick={()=>inputRef.current?.click()}><Upload size={14}/>Încarcă</button><button type="button" onClick={()=>setOpen(state=>!state)}><Images size={14}/>Bibliotecă</button></div>
   </article>}
  </div>
  <p className="premium-media-hint"><GripVertical size={14}/> Poți reordona fotografiile prin glisare. Steaua marchează fotografia principală.</p>
  {open&&<div className="premium-media-library">
   <header><div><span>BIBLIOTECA FLORALIS</span><strong>Alege fotografii existente</strong></div><button type="button" aria-label="Închide biblioteca media" onClick={()=>setOpen(false)}>×</button></header>
   <div className="premium-media-search"><Search size={16}/><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Caută după nume sau descriere…" aria-label="Caută în biblioteca media"/></div>
   <div className="premium-media-library-grid">{available.length?available.map(item=>{const selected=images.some(image=>image.url===item.url);return <button type="button" className={selected?'is-selected':''} disabled={selected||images.length>=max} key={item.id} onClick={()=>onChange([...images,{url:item.url,alt:item.alt||item.name||''}])}><Image src={item.url} alt={item.alt}/><span>{selected?<><Check size={13}/>Adăugată</>:item.name}</span></button>;}):<div className="premium-media-library-empty"><ImageIcon size={24}/><span>Nu am găsit fotografii.</span></div>}</div>
  </div>}
 </section>;
}
